The marginal probability path is defined as
\begin{align*}
    p_t(x) = \sum_{z \in \mathcal{Z}} p_{t|Z}(x|z) p_Z(z).

As shown by \citep{lipman2024flow}, if each conditional path $p_t(x|z)$ is generated by a velocity $u_t(y,x|z)$, the corresponding marginal velocity $u_t(x)$ is given by
\begin{align*}
    u_t(x) = \sum_{z \in \mathcal{Z}} u_t(y,x|z) p_{Z|t}(z|x), \quad \text{where} \quad p_{Z|t}(z|x) = \frac{p_t(x|z) p_Z(z)}{p_t(x)}. 
\end{align*}

\begin{align*}
    \mathcal{L}_{\text{CDFM}} = \mathbb{E}_{t, Z \sim p_Z, X_t \sim p_{t|Z}} \left[ D(u_t(\cdot,X_t|Z), u_t^\theta(\cdot,X_t)) \right].
\end{align*}

To overcome this challenge, we employ factorized velocities \citep{campbell2022continuous, campbell2024generative,gat2024discrete}, which decompose the velocity field as
\begin{align}
\label{eqn:factorized_velocity}
    u_t(y,x) = \sum_i \delta(y^{\widebar{i}}, x^{\widebar{i}}) u^i_t(y^i,x),
\end{align}
where $\delta(\cdot,\cdot)$ is the Kronecker delta and $\widebar{i} := (1,...,i-1,i+1,...,d)$ denotes all indices except $i$.

\begin{align}
\label{eqn:factorized_v_loss}
    \mathcal{L}_{\text{CDFM}} 
    = & ~ \mathbb{E}_{t, Z, X_t \sim p_{t|Z}} \left[ \| u_t(\cdot,X_t|Z) - u_t^\theta(\cdot,X_t) \|_2^2 \right], \nonumber \annot{By the definition of CDFM \eqref{eqn:cdfm_loss_mse}} \\
    = & ~ \mathbb{E}_{t, Z, X_t \sim p_{t|Z}} \left[ \sum_{y \in V^d} \sum_{i \in [d]}  \delta^2(y^{\widebar{i}}, X_t^{\widebar{i}})
    \left(  u^i_t(y^i,X_t|Z) - u^{\theta,i}_t(y^i,X_t) \right)^2 \right], \nonumber 
    \annot{By  \eqref{eqn:factorized_velocity}} \\
    = & ~ \mathbb{E}_{t, Z, X_t \sim p_{t|Z}} \left[ \sum_{i \in [d]} \| u_t^i(\cdot,X_t|Z) - u_t^{\theta,i}(\cdot,X_t) \|_2^2 \right].
\end{align}

The model is trained to match the ground-truth velocity for each coordinate $u^i_t$, resulting in the following CDFM loss objective
\begin{align}
\label{eqn:cdfm_mixture_p}
    \mathcal{L}_{\text{CDFM}}
    = \mathbb{E}_{t, X_0, X_1, X_t \sim p_{t|X_0,X_1}} \left[\sum_{i \in [d]} \| 
    \frac{\dot{\kappa_t}}{1-\kappa_t} 
    [\delta(\cdot,X_1^i) - \delta(\cdot,X_t^i)]  - u_t^{\theta,i}(\cdot,X_t) \|_2^2 \right],
\end{align}
where $\delta(\cdot, z)$ denotes a one-hot vector in $\mathbb{R}^M$ corresponding to a token $z \in \mathcal{V}$.

Given $n$ i.i.d training $\{x_i\}_{i=1}^n$ , the factorized empirical loss used to train the velocity model for coordinate $i_0$ is defined as:
\begin{align}
\label{eqn:cdfm_loss_empirical}
    \widehat{\mathcal{L}}^{i_0}_{\rm CDFM}
    :=  \frac{1}{n} \sum_{i=1}^n \int_{t_0}^T \underset{X_0 \sim p_0,X_t \sim p_{t|x_0=X_0,x_1=x_i}} {{\mathbb{E}}} \|\frac{\dot{\kappa_t}}{1-\kappa_t} 
    [\delta(\cdot,x_i^{i_0}) - \delta(\cdot,X_t^{i_0})] -u^{i_0}_\theta(X_t,t)\|_2^2 \dd t.
\end{align}

\label{thm:error_bound_dfm}
Consider the discrete state space $\mathcal{S} = \mathcal{V}^d$ with vocabulary $\mathcal{V} = \{1, \ldots, M\}$. 
Let $P$ be the true data distribution and let $\widehat{P}$ be the distribution generated by a DFM model using factorized velocity estimators $\widehat{u}_\theta^1, \ldots, \widehat{u}_\theta^d$.
For each coordinate $i_0 \in [d]$, define the factorized risk as the mean squared error of its velocity estimator:
\begin{align*}
    \mathcal{R}^{i_0}(\widehat{\Theta}) 
    := \int_{t_0}^T \underset{X_t\sim p_t(x)}
    {{\mathbb{E}}}\|u^{i_0}(X_t,t) - \widehat{u}^{i_0}_\theta(X_t,t)\|_2^2 \dd t,
\end{align*}
where the time interval is clipped to $[t_0, T]$ to ensure numerical stability and $p_t(x)$ is true probability path generated by factorized velocities $u^1, \ldots, u^d$. Then, the total variation distance between the true and generated distributions is bounded by the sum of the risks from each factorized component:
\begin{align*}
    {\rm TV}(P,\widehat{P})
    \lesssim 
    \sqrt{M} \exp(M_u) 
    \sum_{i_0 \in [d]} \sqrt{\mathcal{R}^{i_0}(\widehat{\Theta})},
\end{align*}
where $M_u$ is the upper bound of estimated velocity such that $\abs{u_t^{\theta,i_0}(y,x)} \leq M_u$ for all $y,x \in \mathcal{S}$.

\label{def:holder_space}
Let $d,d'\in\mathbb{Z}^+$, $\Omega\subset\mathbb{R}^d$, and let $\beta=k+\gamma$ be the smoothness parameter with $k=\lfloor\beta\rfloor\in\mathbb{Z}_{\ge 0}$ and $\gamma\in[0,1)$.  
For a $k$-times differentiable function $f:\Omega\to\mathbb{R}$, the H\"older norm is defined as
\begin{align*}
    \|f\|_{\mathcal{H}^\beta(\Omega)}
    := \sum_{\|\alpha\|_1 \leq k} \|\partial^\alpha f\|_{L^\infty(\Omega)}
       + \sum_{\|\alpha\|_1 = k}\sup_{\substack{x,y\in\Omega\\x\neq y}}
          \frac{|\partial^\alpha f(x)-\partial^\alpha f(y)|}{\|x-y\|^\gamma}.
\end{align*}
The H\"older class with smoothness $\beta$ and radius $K>0$ is then
\begin{align*}
    \mathcal{H}^\beta_{d,d'}(\Omega,K)
    := \{f=(f_1,\dots,f_{d'})^\top:\Omega\to\mathbb{R}^{d'} \mid 
    \sup_{i\in[d']} \|f_i\|_{\mathcal{H}^\beta(\Omega)} \leq K \}.
\end{align*}

\begin{align*}
    \|f\|_{\mathcal{H}^\beta(\Omega)}
    := \sum_{\|\alpha\|_1 \leq k} \|\partial^\alpha f\|_{L^\infty(\Omega)}
       + \sum_{\|\alpha\|_1 = k}\sup_{\substack{x,y\in\Omega\\x\neq y}}
          \frac{|\partial^\alpha f(x)-\partial^\alpha f(y)|}{\|x-y\|^\gamma}.
\end{align*}

\label{lem:bridge_gap_from_discrete_to_continuous}
Let $\mathcal{S} \subset \mathbb{R}^d$ be the discrete state space.
For each $x\in\mathcal{S}$, 
let $t \mapsto u(x,t) \in \mathcal{H}^\beta_{1,M^d}([0,1],K)$ with $\beta=k_1+\gamma\ge 1$, where  $k=\lfloor \beta \rfloor$ and $\gamma\in[0,1)$.  
Then there exists an continuous extension $\widetilde{u} \in \mathcal{H}^{\beta}_{d+1,M^d}(\mathbb{R}^{d}\times[0,1],C)$  such that
\begin{align*}
    \widetilde{u}(s,t)=u(s,t) ~~~~\text{for all}~ s\in\mathcal{S}, t\in[0,1],
\end{align*}
where the H\"older norm $C = e\cdot(k_1+2)(2k_1)^{2k_1} KM^d$.

\label{thm:velocity_estimation_extension_mixture_path}
