Here we set transformer feature dimension $d_0>25$ for simplicity.

The multi-head attention layer $F^{\rm SA}:\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ is then defined as:
\begin{align*}
    F^{\rm SA}(Z):=Z+\sum_{i=1}^hW_O^i(W_V^iZ)\mathop{{\rm Softmax}}((W_K^iZ)^\top(W_Q^iZ)),
\end{align*}
where $W_K^i,W_Q^i,W_V^i,(W_O^i)^\top\in\mathbb{R}^{s\times d}$ are weight matrices for all $i\in[h]$ and $\mathop{{\rm Softmax}}(\cdot)$ is the column-wise softmax function.

The feed-forward layer $F^{\rm FF}(Z):\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ is then defined as:
\begin{align*}
    F^{\rm FF}(Z):=Z+W_2\mathop{\mathsf{ReLU}}(W_1Z+b_1\mathds{1}_L^\top)+b_2\mathds{1}_L^\top,
\end{align*}
where $W_1,(W_2)^\top\in\mathbb{R}^{r\times d}$ are weight matrices, $b_1\in\mathbb{R}^r,b_2\in\mathbb{R}^d$ are bias.

\label{def:transformer_block}
For $h,s,r\in\mathbb{Z}^+$, we define a 
 transformer block $F^{h,s,r}:\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ as:
\begin{align*}
    F^{h,s,r}:=F^{\rm FF}\circ F^{\rm SA},
\end{align*}
where $F^{\rm SA}$ has $h$ heads and hidden dimension $s$, $F^{\rm FF}$ has hidden dimension $r$.

\label{def:transformer_network_function_class}
Let transformer block $F^{h,s,r}$ be as defined in \cref{def:transformer_block}.
Then we define the transformer network function class $\mathcal{T}^{h,s,r}$ as a function class with each component being the composition of transformer blocks:
\begin{align*}
    \mathcal{T}^{h,s,r}=\{\tau:\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L} \mid \tau=F^{h,s,r}\circ\cdots\circ F^{h,s,r}\}.
\end{align*}

\label{def:definition_of_parameter_bound}
Let $F^{\rm E}(Z):=Z+E$ represent the position encoding layer and $R$ represent the reshape layer.
The transformer network class with reshape layer is defined as:
\begin{align*}
    \mathcal{T}^{h,s,r}_R:=\{R^{-1}\circ f_\mathcal{T}\circ F^{\rm E} \circ R:\mathbb{R}^{d_0}\to \mathbb{R}^{d_0} \mid f_\mathcal{T}\in\mathcal{T}^{h,s,r}\}.
\end{align*}
We write $W_{KQ}^i:=(W_K^i)^\top W_Q^i$ and $W_{OV}^i:=W_O^iW_V^i$ for simplicity of notations.
Then, a transformer function class with reshape layer and parameter bound is defined as as $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F},L_\mathcal{T})$, which satisfies:
\begin{itemize}
    \item $h,s,r$ as defined above; 
    \item Transformer output bound: $\sup_Z \|f_\mathcal{T}(Z)\|\leq C_\mathcal{T}$;
    \item Parameter bound in $F^{\rm FF}$: $\max\{\|W_1\|_{2,\infty},\|W_2\|_{2,\infty}\}\leq C^{2,\infty}_{F},~\max\{\|W_1\|_{2},\|W_2\|_{2}\}\leq C^{2}_{F}$;
    \item Parameter bound in $F^{\rm SA}$: $\|W_{KQ}^i\|_2\leq C_{KQ},~\|W_{OV}^i\|_2\leq C_{OV},~\|W_{KQ}^i\|_{2,\infty}\leq C^{2,\infty}_{KQ},~\|W_{OV}^i\|_2\leq C^{2,\infty}_{OV}$;
    \item Parameter bound in $F^{\rm E}$: $\|E^\top\|_{2,\infty}\leq C_E$;
    \item Frobenius Lipschitzness of $f_{\mathcal{T}}\in\mathcal{T}^{h,s,r}$:$\|f_{\mathcal{T}}(Z_1)-f_{\mathcal{T}}(Z_2)\|_F\leq L_\mathcal{T}\|Z_1-Z_2\|_F$.
\end{itemize}

\label{lem:lipschitzness_of_composition}
    Let $f_1,f_2:\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ be $L_1$- and $L_2$-Lipschitz w.r.t. Frobenius norm $\|\cdot\|_F$ respectively.
    Then $f_1\circ f_2$ is $(L_1L_2)$-Lipschitz with respect to $\|\cdot\|_F$.

\label{lem:lipschitzness_of_feedforward}
Let $Z\in \mathbb{R}^{d \times L}$ and define the feedforward layer as
\begin{align*}
    F^{\rm FF}(Z) := Z+W_2\mathop{\mathsf{ReLU}}(W_1Z+b_1\mathds{1}_L^\top)+b_2\mathds{1}_L^\top.
\end{align*}
Then $F^{\rm FF}$ is Lipschitz continuous with respect to Frobenius norm, with Lipschitz constant 
$\|W_1\|_2\cdot\|W_2\|_2+1$.

\label{lem:bound_norm_with_jacobi}
Let $\Delta^{n-1}=\{x\in\mathbb{R}^n|x\geq0,\|x\|_1=1\}$ denote the $n$-simplex.
Suppose $f:\mathbb{R}^d\to\Delta^{n-1}$ is differentiable and satisfies $\|J f(x)\|_2\leq c_f$ for all $x\in\mathbb{R}^d$.
Then for all $x_1,x_2\in\mathbb{R}^d$, it holds:
\begin{align*}
    \|f(x_1)-f(x_2)\|_2\leq c_f\|x_1-x_2\|_2.
\end{align*}

\begin{align*}
    \|f(x_1)-f(x_2)\|_2 \leq & ~
    \|(\int_0^1 J(tx_1+(1-t)x_2) \dd t)(x_1-x_2)\|_2 \\
    \leq & ~
    \int_0^1 \|J(tx_1+(1-t)x_2)(x_1-x_2)\|_2 \dd t \annot{By Jensen's inequality} \\
    \leq & ~
    \int_0^1 \|J(tx_1+(1-t)x_2)\|_2 \cdot \|x_1-x_2\|_2 \dd t \annot{$\|Ax\|_2\leq\|A\|_2\|x\|_2$} \\
    \leq & ~
    c_f\|x_1-x_2\|_2. \annot{$\|J f(x)\|_2\leq c_f$}
\end{align*}

\label{lem:lipschitzness_of_softmax}
Let $\mathop{{\rm Softmax}}(\cdot):\mathbb{R}^{d\times L}\to\mathbb{R}^{d\times L}$ denote the column-wise softmax function.  
Then for all $X_1,X_2\in\mathbb{R}^{d\times L}$, it holds: 
\begin{align*}
\|\mathop{{\rm Softmax}}(X_1)-\mathop{{\rm Softmax}}(X_2)\|_F\leq \|X_1-X_2\|_F.
\end{align*}

For the simplicity of presentation, let $s:\mathbb{R}^d \to \mathbb{R}^d$ denote the (element-wise) softmax function.
Its Jacobian is $J=\mathrm{diag}(s)-ss^\top$.
Thus, $J$ is symmetric and positive semi-definite, so its singular values equal its eigenvalues. 
Recall that for softmax function, its Jacobian matrix's eigenvalues are smaller than 1.
Hence, 
\begin{align*}
    \|J\|_2\leq1.    
\end{align*}

Combining  $\|J\|_2\leq1$ with \cref{lem:bound_norm_with_jacobi}, for each column $i\in[L]$ we have
\begin{align*}
    \|(\mathop{{\rm Softmax}}(X_1)-\mathop{{\rm Softmax}}(X_2))_{\cdot,i}\|_2 \leq \|(X_1-X_2)_{\cdot,i}\|_2.
\end{align*}
Summing over all columns gives
\begin{align*}
    \|\mathop{{\rm Softmax}}(X_1)-\mathop{{\rm Softmax}}(X_2)\|_F\leq \|X_1-X_2\|_F.
\end{align*}
This completes the proof.

\label{lem:lipschtzness_of_self_attention}
Let $X\in\mathbb{R}^{d\times L}$ satisfy $\|X\|_2 \le B_X$ on a compact domain.  
Define $F^{\rm SA}(X):=X+\sum_{i=1}^hW_O^i(W_V^iX)\mathop{{\rm Softmax}}((W_K^iX)^\top(W_Q^iX))$.
Then, $F^{\rm SA}$ is Lipschitz continuous w.r.t. the Frobenius norm $\|\cdot\|_F$, with Lipschitz constant
\begin{align*}
    1+2(B_X)^2\sum_{i=1}^h\|W^i_{OV}\|_2\cdot\|W^i_{KQ}\|_2+L\sum_{i=1}^h\|W^i_{OV}\|_2,
\end{align*}
where $W^i_{OV} = W_O^i W_V^i$ and $W^i_{KQ} = (W_K^i)^\top W_Q^i$ for any $i \in [h]$.

\label{lem:lipschitzness_of_approximator_transformer}
Let 
\begin{align*}
    f_\mathcal{T}:=F^{\rm FF}_1\circ F^{\rm SA}\circ F^{\rm FF}_2,
\end{align*}
be a Transformer block in the class 
