\label{def:tokenwise_separateness}
Let $Z^{(1)},\dots,Z^{(N)}\in\mathbb{R}^{d\times L}$ be embeddings.
Then $Z^{(1)},\dots,Z^{(N)}$ are called tokenwise $(\gamma_{\rm min},\gamma_{\rm max},\delta)$-separated if the following conditions hold:
\begin{enumerate}
    \item [(i)] For any $i\in[N]$ and $k\in[L]$, $\|Z^{(i)}_{:,k}\|>\gamma_{\rm min}$ holds.

    \item [(ii)] For any $i\in[N]$ and $k\in[L]$, $\|Z^{(i)}_{:,k}\|<\gamma_{\rm max}$ holds.

    \item [(iii)] For any $i,j\in[N]$ and $k,m\in[L]$, if $Z^{(i)}_{:,k}\neq Z^{(j)}_{:,m}$, then $\|Z^{(i)}_{:,k}- Z^{(j)}_{:,m}\|>\delta$ holds.
\end{enumerate}


Further, $Z^{(1)},\dots,Z^{(N)}$ are called tokenwise $(\gamma,\delta)$-separated if only (ii) and (iii) hold.
Also, $Z^{(1)},\dots,Z^{(N)}$ are called tokenwise $\delta$-separated if only (iii) holds.

\label{lem:attention_is_contextual_mapping}
Let $Z^{(1)},\dots,Z^{(N)}\in\mathbb{R}^{d\times L}$ be tokenwise $(\gamma_{\rm min},\gamma_{\rm max},\epsilon)$-separated embeddings with the vocabulary set $\mathcal{V}=\cup_{i\in[N]}\mathcal{V}^{(i)}\subset\mathbb{R}^d$.
Assume there are no duplicate token in each sequence; that is, $Z^{(i)}_{:,k}\neq Z^{(i)}_{:,m}$ for $i\in[N]$ and $k,m\in[L]$.
Then there exists a 1-layer single head attention layer that is a $(\gamma,\delta)$-contextual mapping for the embeddings $Z^{(1)},\dots,Z^{(N)}$ with
\begin{align*}
    \gamma=\gamma_{\rm max}+\frac{\epsilon}{4}, ~ \delta=\exp(-\frac{5|\mathcal{V}|^4d\kappa\gamma_{\rm max}\log L}{\epsilon}),
\end{align*}
where $\kappa:=\frac{\gamma_{\rm max}}{\gamma_{\rm min}}$.

Here, we restate the proof of  \citep[Theorem H.2]{su2025high} for completeness.

The proof proceeds in four parts:
\begin{itemize}
    \item Step 1: Approximation using step function

    \item Step 2: Quantization by the first feed-forward layer

    \item Step 3: Contextual mapping through the self-attention layer

    \item Step 4: Memorization via the second feed-forward layer
\end{itemize}


\textbf{Step 1: Approximation using Step Function.}
We assume the domain of $f$ is $\Omega=[-I,I]^{d\times L}$.

Then we construct the grid $\mathbb{G}_D$ as :
\begin{align*}
    \mathbb{G}_D:=\{C\in\Omega|C_{i,k}=-I+\frac{s_{i,k}}{D},s_{i,k}=1,\dots,2ID,\}
\end{align*}
where $D>0$ is the grid granularity.
Given $Z\in\Omega$, we approximate $f$ via the step function
\begin{align*}
    g_1(Z)=\sum_{C\in\mathbb{G}_D}f(C)\mathds{1}\{Z\in C+[-1/D,0)^{d\times L}\}.
\end{align*}
By uniform continuity of $f$ , there exists $D$ such that 
\begin{align*}
    d_F(f,g_1)<\frac{\epsilon}{3}.
\end{align*}
Then we use a transformer to approximate the step function $g_1(Z)$.

\textbf{Step 2: Quantization by the First Feed-forward Layer.}
The quantification function we want to approximate consists of two parts, namely, the quantize function and the penalty function.
We approximate two parts separately.

\begin{itemize}

\item \textbf{Quantize Function} 
We define the quantization function ${\rm quant}_D:\mathbb{R}\to \mathbb{R}$:
\begin{align*}
    {\rm quant}_D(z):=
    \begin{cases}
    -I & ~ z<-I, \\
    -I+1/D & ~ -I\leq z <-I+1/D, \\
    \vdots & ~ \vdots \\
    I & ~ I-1/D\leq z.
    \end{cases}
\end{align*}
Further, we define the quantize function ${\rm quant}^{d\times L}_D(Z):\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ as the entrywise quantize function, such that $({\rm quant}^{d\times L}_D(Z))_{t,k}={\rm quant}_D(Z_{t,k})$.
Notice that ${\rm quant}_D(z)$ is approximated through the following function by taking sufficiently small $\delta$:
\begin{align}\label{eq:quantization_part_quant_approximation_construction}
    f_1(z):=-I+\sum_{t=-ID}^{I(D-1)}\frac{\rm RELU[z/\delta-t/\delta D]-\mathop{\mathsf{ReLU}}[z/\delta-1-t/\delta D]}{D}.
\end{align}
That's to say, there exists RELU feed-forward network approximating ${\rm quant}^{d\times L}_D(Z)$.

\item \textbf{Penalty Function} 
We define the penalty function ${\rm penalty}:\mathbb{R}\to \mathbb{R}$:
\begin{align*}
    {\rm penalty}(z):=
    \begin{cases}
    -1 & ~ z<-I, \\
    0 & ~ z\in[-I,I], \\
    1 & ~ z>I.
    \end{cases}
\end{align*}
Further, we define the penalty function ${\rm penalty}^{d\times L}(Z):\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ as the entrywise penalty function, such that $({\rm penalty}^{d\times L}(Z))_{t,k}={\rm quant}_D(Z_{t,k})$.
Notice that ${\rm penalty}(z)$ is approximated through the following function by taking sufficiently small $\delta$:
\begin{align}\label{eq:quantization_part_penalty_approximation_construction}
    f_2(z)= & ~\mathop{\mathsf{ReLU}}[(z-I)/\delta]-\mathop{\mathsf{ReLU}}[(z-I)/\delta+1]\notag\\
    & ~ +
    \mathop{\mathsf{ReLU}}[(-z-I)/\delta]-\mathop{\mathsf{ReLU}}[(-z-I)/\delta+1]
\end{align}
That's to say, there exists RELU feed-forward network approximating ${\rm penalty}^{d\times L}(Z)$.
\end{itemize}

Altogether, we define $g_2(Z):\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ as :
\begin{align*}
    g_2(Z):=\frac{{\rm quant}^{d\times L}_D(Z)+I}{2I}+{\rm penalty}^{d\times L}(Z).
\end{align*}
$g_2(Z)$ map $[-I,I]^{d\times L}$ into normalized grid $\mathbb{G}_D^{\rm norm}\subset[0,1]^{d\times L}$ with gride granularity $2ID$.
At the same time, $g_2(Z)$ guarantees non-positive outputs on domain $\mathbb{R}^{d\times L}\backslash[-I,I]^{d\times L}$.
We use $f_1(z)$ and $f_2(z)$ introduced above to construct the first feed-forward layer $F^{\rm FF}_1$.

\textbf{Step 3: Contextual Mapping through the Self-attention Layer.}
Let $\widebar{\mathbb{G}}_D$ denote the following sub-grid class on $[0,1]^{d\times L}$:
\begin{align*}
    \widebar{\mathbb{G}}_D:=\{G\in\mathbb{G}_D^{\rm norm} \mid {\rm for ~ all ~}k,m\in[L],G_{:,k}\neq G_{:,m}\}.
\end{align*}
The by definition, $\widebar{\mathbb{G}}_D$ is a token class with token-wise $((2ID)^{-1},\sqrt{d},(2ID)^{-1})$-separated sequence.
Following the construction of $F^{\rm SA}$ in proof of \citep[Theorem H.2]{su2025high}, for sufficiently large $D$ we have:
\begin{align*}
    F^{\rm SA}\circ F^{\rm FF}_1(Z)_{t,k} < & ~
    \frac{1}{4D} \quad {\rm for ~all }\quad  Z\in\mathbb{R}^{d\times L}\backslash [-I,I]^{d\times L},\quad
    t\in[d],k\in[L], \\
    F^{\rm SA}\circ F^{\rm FF}_1(Z)_{t,k} > & ~
    \frac{3}{4D} \quad {\rm for ~all }\quad Z\in [-I,I]^{d\times L},\quad t\in[d],k\in[L].
\end{align*}

\textbf{Step 4: Memorization via the Second Feed-forward Layer.}
Finally, we construct a bump function of scale $R>0$ to map every $c\in\widebar{\mathbb{G}}_D$ to its label $f(C)$ and sends any sequence that lies component-wise below the threshold $1/(4D)$ to zero.
Precisely, for each $C\in\mathbb{G}_D^{\rm norm}$ we construct a bump function of scale $R$:
\begin{align}\label{eq:memorization_part_bump_construction}
    {\rm bump}_R(Z)= & ~\frac{f(2C-I)}{dL}\sum_{t=1}^d\sum_{k=1}^L({\rm RELU[R(Z_{t,k}-C_{t,k})-1]} \notag\\
    & ~ 
    -\mathop{\mathsf{ReLU}}[R(Z_{t,k}-C_{t,k})]+\mathop{\mathsf{ReLU}}[R(Z_{t,k}-C_{t,k})+1]).
\end{align}
Summing up over $C\in\mathbb{G}_D^{\rm norm}$ and we obtain the second feed-forward layer $F_2^{\rm FF}$.

We sum up the error bound in four steps.
As discussed in the step approximation using step function, there exists $D$ such that 
\begin{align*}
    d_F(f,g_1)<\frac{\epsilon}{3}.
\end{align*}
By choosing sifficiently quantization step $\delta>0$, we obtain
\begin{align*}
    d_F(F^{\rm FF}_2\circ F^{\rm SA}\circ F^{\rm FF}_1,F^{\rm FF}_2\circ F^{\rm SA}\circ g_2)<\frac{\epsilon}{3}.
\end{align*}
By choosing granularity $D$ large enough, $|\mathbb{G}_D\backslash\mathbb{G}_D^{\rm norm}|$ is negligible.
Then we have for large enough $D$ and $R$,
\begin{align*}
    d_F(F^{\rm FF}_2\circ F^{\rm SA}\circ g_2,g_1)<\frac{\epsilon}{3}.
\end{align*}
Altogether, summing up the error we have:
\begin{align*}
    d_F(f(Z),g(Z))<\epsilon.
\end{align*}
This completes the proof.

