\label{thm:parameter_norm_bound_for _approximator_transformer}
Let $\epsilon\in(0,1)$.
Consider $Z\in[-I,I]^{d\times L}$ be input sequence, where $I>0$ and $L>2$.
Let Let $f(Z):[-I,I]^{d\times L}\to \mathbb{R}^{d\times L}$ be a Lipschitz continuous function with respect to Frobenius norm on a bounded domain.
Then for the approximator $g(Z)=F^{\rm FF}_1\circ F^{\rm SA}\circ F^{\rm FF}_2\in\mathcal{T}^{h,s,r}$ in \cref{thm:universal_approximation_no_parameter_bound} within $\epsilon$ precision, i.e., $d_F(f,g)<\epsilon$, the parameter bound in the transformer network class follow:
\begin{align*}
    & ~C_{KQ},C^{2,\infty}_{KQ}=O(I^{4d+2}\epsilon^{-4d-2}L^{2d+1}\log L);C_{OV},C^{2,\infty}_{OV}=O(\epsilon L^{-1/2}) \notag\\
    & ~C_{F},C^{2,\infty}_{F}=O(I\epsilon^{-1}L\cdot\max\|f(Z)\|_F);C_E=O(L),
\end{align*}
where $O(\cdot)$ hides polynomial factors depending on $d$.

The proof is modified from proof of \citep[Lemma H.4]{su2025high}.

Recall that we take sufficiently large $D,R$ and sufficiently small $\delta$ in proof of \cref{thm:universal_approximation_no_parameter_bound} to ensure the precision.
We then start with bounding $D,R,\delta$ in terms of $\epsilon$. 

\begin{itemize}

\item \textbf{Bound on $\delta$.}
Recall the approximation in \eqref{eq:quantization_part_quant_approximation_construction} and \eqref{eq:quantization_part_penalty_approximation_construction}.
To guarantee the effect of grid, we hope partition $(i/D,i/D+\delta)$ is a contained in the interval $(i/D,(i+1)/D)$ where $i\in \mathbb{Z}^+$.
Then it's sufficient to take $\delta=o(1/D)$.

\item \textbf{Bound on $D$.}
For Lipschitz continuous function $f$ with respect to Frobenius norm with Lipschitz constant $L_f$, we have
\begin{align*}
    d_F(f(Z),g_1(Z))\leq L_f\|Z-Z^*\|_F\leq2\sqrt{dL}L_f/D,
\end{align*}
where $Z^*={\rm argmin}_{Z'\in\widebar{\mathbb{G}}_D}\|Z-Z'\|_F$.
Then we take $D=O(\epsilon^{-1}\sqrt{L})$.

\item \textbf{Bound on $R$.}
To obtain the correct labeling in \eqref{eq:memorization_part_bump_construction}, we need $S_{t,k}:=Z_{t,k}-C_{t,k}\in(0,1/R)$ for all $t\in[d],k\in[L]$.
Then since $C_{t,k}$ is defined on $\mathbb{G}^{\rm norm}_D$ with granularity $2DI$ and is chosen close enough to $Z_{t,k}$, it suffices to set $R=O(DI)$.

\end{itemize}

Next, we get the norm bound of matrices on the basis of computation above.
Since the $F^{\rm SA}$ is a single head self-attention layer, we directly write $W_K^1,W_Q^1,W_V^1,W_O^1$ as $W_K,W_Q,W_V,W_O$ for simplicity of notations.

\begin{itemize}

\item \textbf{Bound on Norm of $W_{KQ}$.}
Recall that in the proof of Theorem H.1 of \citep{su2025high}, $W_K$ and $W_Q$ follows the construction of 
\begin{align*}
    W_K=\sum_{i=1}^\rho p_iq_i^\top\in\mathbb{R}^{s\times d},W_Q=\sum_{i=1}^\rho p_i'q_i'^\top\in\mathbb{R}^{s\times d},
\end{align*}
where $p_i^\top p_i'=(|\mathcal{V|}+1)^4d\log L/(\epsilon_s\gamma_{\rm min})$.
Then we have
\begin{align*}
    & ~\|W_{KQ}\|_2\leq 
    \|W_{KQ}\|_F=\|W_K^\top W_Q\|_F=O(\frac{4\log L|V|^4}{\epsilon_s\gamma_{\rm min}}), \\
    & ~\|W_{KQ}\|_{2,\infty}= 
    \|W_K^\top W_Q\|_{2,\infty}=O(\frac{4\log L|V|^4}{\epsilon_s\gamma_{\rm min}}).
\end{align*}
Recall that input $\widebar{\mathbb{G}}_D$ is a token class with token-wise $((2ID)^{-1},\sqrt{d},(2ID)^{-1})$-separated sequence.
Then $|V|=O((DI)^d)$ and $\gamma_{\rm min},\epsilon_s=(2DI)^{-1}$.
Finally, by $D=O(\epsilon^{-1}\sqrt{L})$, we get
\begin{align*}
    \|W_{KQ}\|_2,\|W_{KQ}\|_{2,\infty}= O(\epsilon^{-4d-2}I^{4d+2}L^{2d+1}\log L).
\end{align*}

 \item \textbf{Bound on Norm of $W_{OV}$.}
Recall that in the proof of Theorem H.1 of \citep{su2025high}, $W_O$ and $W_V$ follows the construction of 
\begin{align*}
    W_O=\sum_{i=1}^\rho p_i''q_i''^\top\in\mathbb{R}^{s\times d},W_V=\sum_{i=1}^\rho p_i''''p_i''^\top\in\mathbb{R}^{d\times s},
\end{align*}
where $\|p_i'''\|\lesssim\epsilon_s/(4\rho\gamma_{\rm max}\|p_i''\|)$ and $p_i''\in\mathbb{R}^s$ is any nonzero vector.
Then with the $(\gamma_{\rm min}=1/D,\gamma_{\rm max}=\sqrt{d},\epsilon_s=1/D)$-separateness and $D=O(\epsilon^{-1}\sqrt{L}),\rho<d$, we get:
\begin{align*}
    & ~ \|W_V\|_2=\sup_{\|x\|_2=1}\|W_Vx\|_2\leq O(\sqrt{\rho}) \leq O(\sqrt{d}), \\
    & ~ \|W_V\|_{2,\infty}=\max_{1\leq i\leq d}\|(W_V)_{(i,:)}\|_2 \leq O(\rho)\leq O(d), \\
    & ~ \|W_O\|_2=\sup_{\|x\|_2=1}\|W_Ox\|_2 \leq O(\sqrt{\rho}\cdot\rho^{-1}\cdot\gamma^{-1}_{\rm max}\cdot \epsilon_s)=O(d^{-1}\epsilon L^{-1/2}), \\
    & ~ \|W_O\|_{2,\infty}=\max_{1\leq i\leq d}\|(W_O)_{(i,:)}\|_2 \leq O(\rho\cdot\rho^{-1}\cdot\gamma^{-1}_{\rm max}\cdot \epsilon_s)=O(d^{-1/2}\epsilon L^{-1/2}).
\end{align*}
Therefore we get:
\begin{align*}
    \|W_{OV}\|_2=\|W_OW_V\|_2\leq O(\epsilon L^{-1/2}), \|W_{OV}\|_{2,\infty}=\|W_OW_V\|_{2,\infty}\leq O(\epsilon L^{-1/2}).
\end{align*}

\item \textbf{Bound on Norm of $W_1^1$ and $W_2^1$ in $F^{\rm FF}_1$.}
Recall that in the construction of the first feed-forward layer, we have two key approximator:
\begin{align*}
    f_1(z):=-I+\sum_{t=-ID}^{I(D-1)}\frac{\rm RELU[z/\delta-t/\delta D]-\mathop{\mathsf{ReLU}}[z/\delta-1-t/\delta D]}{D},
\end{align*}
and 
\begin{align*}
    f_2(z)= & ~\mathop{\mathsf{ReLU}}[(z-I)/\delta]-\mathop{\mathsf{ReLU}}[(z-I)/\delta+1]+\\
    & ~
    \mathop{\mathsf{ReLU}}[(-z-I)/\delta]-\mathop{\mathsf{ReLU}}[(-z-I)/\delta+1].
\end{align*}
Then for $t\in[d],k\in[L]$, we approximate each entry of $g_1(Z)$ with
\begin{align*}
    F^{\rm FF}_1(Z)_{t,k}=\frac{f_1(Z_{t,k})+I}{2I}+f_2(Z_{t,k}).
\end{align*}
That's to say, each element in $W_1$ and $W_2$ is bounded by $1/\delta$ and $I$.
Recall that $\delta=o(1/D)$ and $D=O(\epsilon^{-1}\sqrt{L})$, we have
\begin{align*}
    \max\{\|W_1^1\|_2,\|W_2^1\|_2\}\leq O(\epsilon^{-1}L),\max\{\|W_1^1\|_{2,\infty},\|W_2^1\|_{2,\infty}\}\leq O(\epsilon^{-1}L).
\end{align*}

\item \textbf{Bound on Norm of $W_1^2$ and $W_2^2$ in $F^{\rm FF}_2$.}
Recall that in the construction of the second feed-forward layer, we construct $F^{\rm FF}_2$ through bump function:
\begin{align*}
    {\rm bump}_R(Z)= & ~\frac{f(2C-I)}{dL}\sum_{t=1}^d\sum_{k=1}^L({\rm RELU[R(Z_{t,k}-C_{t,k})-1]} \\
    & ~ 
    -\mathop{\mathsf{ReLU}}[R(Z_{t,k}-C_{t,k})]+\mathop{\mathsf{ReLU}}[R(Z_{t,k}-C_{t,k})+1]).
\end{align*}
Therefore, the output of $F^{\rm FF}_2$ is bounded by $R$ and $\max\|f(Z)\|_F$.
Then by $R=O(DI)$ and $D=O(\epsilon^{-1}\sqrt{L})$, we have:
\begin{align*}
    & ~\max\{\|W_1^2\|_2,\|W_2^2\|_2\}\leq O(I\epsilon^{-1}L\cdot\max\|f(Z)\|_F), \\
    & ~\max\{\|W_1^2\|_{2,\infty},\|W_2^2\|_{2,\infty}\}\leq O(I\epsilon^{-1}L\cdot\max\|f(Z)\|_F).
\end{align*}

\item \textbf{Bound on Norm of Encoding Matrix $E$.}
By Corollary 2 of \citep{kajitsuka2023transformers}, it suffices to take the encoding matrix $E$:
\begin{align*}
E=
    \begin{bmatrix}
        2\gamma_{\rm max} & 4\gamma_{\rm max} & \dots & 2L\gamma_{\rm max} \\
         2\gamma_{\rm max} & 4\gamma_{\rm max} & \dots & 2L\gamma_{\rm max} \\
         \vdots & \vdots & &\vdots \\
         2\gamma_{\rm max} & 4\gamma_{\rm max} & \dots & 2L\gamma_{\rm max}
    \end{bmatrix}.
\end{align*}
Recall that we have $\gamma_{\rm max}=\sqrt{d}$, then we obtain:
\begin{align*}
    \|E^\top\|_{2,\infty}=\sqrt{4dL^2}\gamma_{\rm max}=O(L).
\end{align*}
\end{itemize}
This complete the proof.

