\label{def:tv_distance}
Let $P$ and $Q$ be two probability distributions defined on a discrete state space $S$, with corresponding probability mass functions $p(x)$ and $q(x)$. 
Then the total variation (TV) distance between them is defined as:
\begin{align*}
    \text{TV}(P,Q) := \frac{1}{2} \sum_{x \in S} |p(x)-q(x)|.
\end{align*}

\label{lem:grönwall_inequality}
Let $a,b\in\mathbb{R}$ satisfy $a<b$.
Let $y(t)$ and $f(t)$ be two real value function defined on $[a,b]$.
Suppose that $y(t)$ is differentiable on $[a,b]$ and satisfies:
\begin{align*}
    \frac{\dd }{\dd t}y(t)\leq y(t)f(t), t\in[a,b].
\end{align*}
Then we have:
\begin{align*}
    y(b)\leq y(a)\exp(\int_a^b f(s) \dd s).
\end{align*}

\label{lem:error_integral_formula}
Let the true probability vector $p_t$ and the estimated vector $p_{t,\theta}$ be solutions to the linear differential systems
\begin{align}
\label{eq:differential_system_matrix_form}
    \begin{cases}
    \frac{\dd}{\dd t}p_t= U_tp_t, \\
    \frac{\dd}{\dd t}p_{t,\theta}= U_{t,\theta}p_{t,\theta},
    \end{cases}
\end{align}
with a shared initial condition $p_0 = p_{0,\theta}$. 
Let the evolution operator for the estimated system be $\mathcal{P}_{s,t,\theta}\in\mathbb{R}^{|S|\times|S|}$, which is the solution to $\frac{\dd}{\dd t}\mathcal{P}_{s,t,\theta} = U_{t,\theta}\mathcal{P}_{s,t,\theta}$ with $\mathcal{P}_{s,s,\theta}=I$. 
The difference between the distributions at time $t>0$ is given by
\begin{align*}
    p_{t,\theta} - p_t
    = \int_0^t \mathcal{P}_{s,t,\theta}(U_{s,\theta}-U_s)p_s \dd s.
\end{align*}

We construct the helping function $Z(s)$ as:
\begin{align}\label{eq:construction_of_auxiliary_function_estimation}
    Z(s)=\mathcal{P}_{s,t,\theta}p_s.
\end{align}
Then since $\mathcal{P}_{s,t,\theta}$ and $p_s$ is differentiable, we have:
\begin{align}
    \frac{\dd}{\dd s}Z(s) = & ~(\frac{\dd}{\dd s}\mathcal{P}_{s,t,\theta})p_s+\mathcal{P}_{s,t,\theta}(\frac{\dd}{\dd s}p_s) \annot{By \eqref{eq:construction_of_auxiliary_function_estimation}}\\
    = & ~
    (-\mathcal{P}_{s,t,\theta}U_{s,\theta})p_s+\mathcal{P}_{s,t,\theta}(U_sp_s) 
    \annot{By backward Kolmogorov Equation \eqref{eq:kolmogorov} and \eqref{eq:differential_system_matrix_form}}\\
    = & ~ \label{eq:differential_of_auxiliary_function}
    -\mathcal{P}_{s,t,\theta}(U_{s,\theta}-U_s)p_s.
\end{align}
Integrating \eqref{eq:differential_of_auxiliary_function}, we obtain:
\begin{align*}
    -\int_0^t \mathcal{P}_{s,t,\theta}(U_{s,\theta}-U_s)p_s \dd s=\int_0^t \frac{\dd}{\dd s}Z(s) \dd s= Z(t)-Z(0)=p_t-p_{t,\theta}.
\end{align*}
This completes the proof.

\begin{align}
    \frac{\dd}{\dd s}Z(s) = & ~(\frac{\dd}{\dd s}\mathcal{P}_{s,t,\theta})p_s+\mathcal{P}_{s,t,\theta}(\frac{\dd}{\dd s}p_s) \annot{By \eqref{eq:construction_of_auxiliary_function_estimation}}\\
    = & ~
    (-\mathcal{P}_{s,t,\theta}U_{s,\theta})p_s+\mathcal{P}_{s,t,\theta}(U_sp_s) 
    \annot{By backward Kolmogorov Equation \eqref{eq:kolmogorov} and \eqref{eq:differential_system_matrix_form}}\\
    = & ~ \label{eq:differential_of_auxiliary_function}
    -\mathcal{P}_{s,t,\theta}(U_{s,\theta}-U_s)p_s.
\end{align}

\label{thm:dfm_error_bound_general}
Consider the discrete state space $\mathcal{S} = \mathcal{T}^d$, where the vocabulary is $\mathcal{T} = \{1, \ldots, M\}$. 
Let $P$ be the true data distribution over $\mathcal{S}$. 
Let $\widehat{u}_\theta$ be the velocity estimator, with parameters $\widehat{\Theta}$ and let $\widehat{P}$ be the distribution generated using this estimator.
Define the risk of the velocity estimator as 
\begin{align*}
    \mathcal{R}(\widehat{\Theta}) := \int_0^1 \underset{X_t\sim p_t(x)}{{\mathbb{E}}}\|u(X_t,t)-u_{\widehat{\theta}}(X_t,t)\|_2^2 \dd t,
\end{align*}
where $p_t(x)$ is the true probability path. Then, the total variation distance between the true and generated distributions is bounded by the risk of this estimator:
\begin{align*}
    \text{TV}(P,\widehat{P})
    \lesssim 
    \exp(M_u) M^{\frac{d}{2}}
    \sqrt{\mathcal{R}(\widehat{\Theta})},
\end{align*}
where $M_u$ is the upper bound of the true velocity field, satisfying $\underset{y,x \in S, t \in [0,1]}{\max} |u_t(y,x)| \leq M_u$.

\begin{align*} 
    \begin{cases}
    \frac{\dd}{\dd t}p_t= U_t p_t, \\
    \frac{\dd}{\dd t}\widehat{p}_{t,\theta}= \widehat{U}_{t,\theta} p_{t,\theta},\\
    p_0= \widehat{p}_{0,\theta}\sim P_0.
    \end{cases}
\end{align*}

\begin{align}
\label{eq:bound_on_evolution_operator_partial_norm}
    \frac{\partial}{\partial t}\|\mathcal{P}_{s,t,\theta}\|_1 \annot{By the Lipschitz continuous of $\ell_1$ norm} 
    \leq & ~
    \|\frac{\partial}{\partial t}\mathcal{P}_{s,t,\theta}\|_1 \notag\\
    = & ~ 
    \|U_{t,\theta}\mathcal{P}_{s,t,\theta}\|_1 \annot{By Kolmogorov Equation} \\
    \leq & ~ \|U_{t,\theta}\|_1 \|\mathcal{P}_{s,t,\theta}\|_1 \annot{By triangle inequality} \\
    \leq & ~ 2M_u \|\mathcal{P}_{s,t,\theta}\|_1, 
\end{align}

\begin{align*}
    \text{TV}(P,\widehat{P})
    \leq & ~ 
    \int_0^1 \|\mathcal{P}_{s,1,\theta}\|_1 
    \|(U_{s,\theta}-U_s)p_s\|_1 \dd s \annot{By \eqref{eq:bound_on_tv_distance}} \\
    \leq & ~
    \int_0^1 \exp(M_u) 
    \|(U_{s,\theta}-U_s)p_s\|_1 \dd s \\
    \lesssim & ~
    \exp(M_u) M^{\frac{d}{2}}
    \sqrt{\mathcal{R}(\widehat{\Theta}))}. 
    \annot{By the definition of risk function $\cal{R}$}
\end{align*}

\label{thm:main_proof_dfm_error_bound}
Consider the discrete state space $\mathcal{S} = \mathcal{T}^d$ with vocabulary $\mathcal{T} = \{1, \ldots, M\}$. 
Let $P$ be the true data distribution and let $\widehat{P}$ be the distribution generated by a DFM model using factorized velocity estimators $\widehat{u}_\theta^1, \ldots, \widehat{u}_\theta^d$.
For each coordinate $i_0 \in [d]$, define the factorized risk as the mean squared error of its velocity estimator:
\begin{align*}
