\label{lem:property_of_bump_function}
Define $\eta(x):[0,\infty)\to [0,1]$ by
\begin{align*}
\eta(x)=
\begin{cases}
    e\cdot\exp(-\frac{1}{1-x}),~ & x\in[0,1), \\
    0,                  ~ & x\in[1,\infty).
\end{cases}
\end{align*}
Then $\eta(t)\in C^\infty$ and $|\frac{\dd^n\eta}{\dd x^n}(x)|\leq e\cdot(\frac{2n}{e})^{2n}$ for all $x\in[0,1]$.

\begin{align*}
    & ~ 
    \frac{\dd^n\eta}{\dd x^n}(x)\\
    = & ~
    \frac{\dd}{\dd x}(\frac{\dd^{n-1}\eta}{\dd x^{n-1}})(x) \\
    = & ~
    \frac{\dd}{\dd x}(e\cdot p_{n-1}(\frac{1}{x-1})\cdot\exp(\frac{1}{x-1})) \\
    = & ~
    e\cdot (-\frac{1}{(x-1)^2}p'_{n-1}(\frac{1}{x-1})+-\frac{1}{(x-1)^2}p_{n-1}(\frac{1}{x-1}))\cdot\exp(\frac{1}{x-1}). \annot{By chain rule}
\end{align*}

\begin{align*}
    \lim_{x\to 1^-}\frac{\dd^n\eta}{\dd x^n}(x) 
    = & ~
    \lim_{x\to 1^-} e \cdot p_n (\frac{1}{x-1})\exp(\frac{1}{x-1}) \annot{By \eqref{eqn:eta_n}}\\
    = & ~ 
    \lim_{x\to -\infty}e\cdot p_n(x)\cdot e^{x}
    \annot{By setting $z=\frac{1}{x-1}$}\\
    = & ~  0 
    \annot{$({\rm polynomial})\cdot e^z$ vanishes as $z\to-\infty$}\\
    = & ~ \lim_{x\to 1^+}\frac{\dd^n\eta}{\dd x^n}(x),
    \annot{By $\eta(x)=0$ for $x>1$}
\end{align*}

\label{lem:bridge_gap_from_discrete_to_continuous_re}
Let $\mathcal{S}\subset\mathbb{R}^d$ be the state space of discrete flow matching.
Recall that $\mathcal{S} \subset \mathbb{R}^d$ is a $1$-separated finite set with $|\mathcal{S}|=M^d$, i.e., $\|s-s'\|\ge1$ for all distinct $s,s'\in\mathcal{S}$.
For each $x\in\mathcal{S}$, 
let $u(x,\cdot)\in\mathcal{H}^\beta_{1,M^d}([0,1],K)$ with $\beta=k_1+\gamma\ge 1$ and $k_1=\lfloor\beta\rfloor$. 
Then there exists an extension $\widetilde{u}:\mathbb{R}^d\times[0,1]\to\mathbb{R}$ such that
\begin{align*}
    \widetilde{u}(x,t) \in \mathcal{H}^{\beta}_{d+1,M^d}(\mathbb{R}^{d}\times[0,1],e\cdot(k_1+2)(2k_1)^{2k_1} KM^d),
\end{align*}
and $\widetilde{u}(s,t)=u(s,t)$ for all $s\in\mathcal{S}$ and $t\in[0,1]$.

Our proof consists of five steps.
We give the construction of $\widetilde{u}(x,t)$ first in \textbf{Step 1 \& 2}, and then prove that it has desired properties in \textbf{Step 3 - 5}.

\textbf{Step 1: Partition of Unity around $\mathcal{S}$.}



Let $\eta(t)$ be the bump function from \cref{lem:property_of_bump_function}.

Let $r=1/e<1/2$.
For $s\in\mathcal{S}\subset \mathbb{R}^d$, we define $\phi^r_s(x):\mathbb{R}^d\to \mathbb{R}$ as
\begin{align*}
\phi^r_s(x) := \eta(\frac{\|x-s\|^2}{r^2}).
\end{align*}

Then $\phi^r_s(x)\in C^\infty$, ${\rm supp}~ \phi^r_s(x) \subset B(s,r)=\{x\in\mathbb{R}^d \mid \|x-s\|<r\}$, and $\phi^r_s(s)=1$.
Since $\mathcal{S}$ is $1$-separated and $r<1/2$, the supports $\{\mathrm{supp}(\phi_s)\}_{s\in\mathcal{S}}$ are pairwise disjoint.


\textbf{Step 2: Extension.}
Next, we extend the discrete function $u$ to a continuous function $\widetilde{u}$.



We construct $\widetilde{u}(x,t)$ as:
\begin{align}
\label{eq:construction_of_tilde_u}
\widetilde{u}(x,t)=\sum_{s\in \mathcal{S}} \phi_s(x)\cdot u(s,t). 
\end{align}
Disjointness implies that for each fixed $x$ at most one term in \eqref{eq:construction_of_tilde_u} is nonzero.
Hence, $\widetilde u(s,t)=u(s,t)$ for all $s\in\mathcal{S}$.





\textbf{Step 3: Derivative Bounds up to Order $k_1$.}
We now prove $\widetilde{u}(x,t)\in \mathcal{H}^{\beta'}_{d,M^d}(\mathbb{R}^d\times[0,1],K')$.

Let $(\lambda,m)$  be multi‑indices with $\lambda\in\mathbb{N}_0^d$, $m\in\mathbb{N}_0$, and $|\lambda|+m\le k_1$.  

Since $\phi_s$ is independent of $t$ and $u(s,\cdot)$ is independent of $x$
\begin{align*}
    \partial_x^\lambda\partial_t^m \widetilde u(x,t)
    = \sum_{s\in\mathcal{S}} \partial_x^\lambda \phi_s (x) \partial_t^m u(s,t),
\end{align*}
or in component-wise form, for every $k\in\mathbb{R}^d$, it holds:
\begin{align*}
\partial_x^\lambda\partial_t^m \widetilde{u}_k(x,t)=\sum_{s\in \mathcal{S}}\partial^\lambda_x\phi_s(x)\partial^{m}_t u_k(s,t).
\end{align*}
Further,  for all $s\in \mathcal{S}$, $x\in\mathbb{R}^d$ and $j\in [d]$, it holds
\begin{align*}
|\frac{\partial}{\partial x[j]}\phi_s(x)| = 
|\frac{2(x[j]-s[j])}{r^2}\eta'(\frac{\|x-s\|^2}{r^2})|.
\end{align*}
Then with $|s[j]-x[j]|\leq\frac{1}{e}$ when $x\in{\rm supp}\{\phi_s(x)\}$, using mathematical induction we get that for all $s\in \mathcal{S}$, $x\in\mathbb{R}^d$ and $m\in\mathbb{Z}^+$, it holds 
\begin{align*}
    |\partial_x^\lambda\partial_t^m\phi_s(x)| \leq \frac{1}{r^{2m}} \cdot |\frac{\dd^m\eta}{\dd x^m}(\frac{\|x-s\|^2}{r^2})|.
\end{align*}

By \cref{lem:property_of_bump_function} and $r=1/e$, we have $|\frac{\dd^m\eta}{\dd x^m}(x)|\leq e\cdot(\frac{2m}{e})^{2m}$ and hence
\begin{align}
    \label{eq:bound_of_phi_derivative}
    \|\partial_x^\alpha \phi_s\|_{L^\infty(\mathbb{R}^d)}
    \le e(2|\alpha|)^{2|\alpha|}
    \quad
    \text{for all}\quad s\in\mathcal{S}.
\end{align}





\textbf{Step 4: $\gamma$-H\"older Seminorm for Order $k_1$.}
Return to the discussion of $\widetilde{u}_k$. 

Let $|\lambda|+m=k_1$. 
For $(x,t_1),(y,t_2)\in\mathbb{R}^d\times[0,1]$ and for every $k\in [M^d]$, we have
\begin{align}
    \sum_{\|\lambda\|_1+m\leq k_1} \|\partial_x^\lambda\widetilde{u}_k(x,t)\|_{L^\infty} 
    \leq & ~ 
    \sum_{\|\lambda\|_1+m\leq k_1}\sum_{s\in \mathcal{S}} \|\partial_x^\lambda\phi_s(x)\partial^{m}_t u_k(s,t)\|_{L^\infty} 
    \annot{By \eqref{eq:construction_of_tilde_u}}\\
    \leq & ~
    e\cdot(2k_1)^{2k_1} \sum_{m\leq k_1}\sum_{s\in \mathcal{S}} \|\partial^{m}_t u_k(s,t)\|_{L^\infty} 
    \annot{By \eqref{eq:bound_of_phi_derivative}}\\
    = & ~
    e\cdot(2k_1)^{2k_1} \sum_{s\in \mathcal{S}} \sum_{m\leq k_1}\|\partial^{m}_t u_k(s,t)\|_{L^\infty} \annot{Interchange the order of summations}\\
    \leq & ~
    \label{eq:bound_on_derivative_part}
    e\cdot(2k_1)^{2k_1} KM^d,
\end{align}
where the last line follows that $u(s,t)\in\mathcal{H}^\beta_{1,M^d}([0,1],K)$ with respect to $t$.
Also, we have
\begin{align}
    & ~ \sum_{\|\lambda\|_1+m =  k_1}\sup_{\substack{{(x,t_1),(y,t_2)\in\mathbb{R}^d\times[0,1]}\\(x,t_1)\neq(y,t_2)}} \frac{|\partial_x^\lambda\partial_t^m\widetilde{u}_k(x,t_1)-\partial_x^\lambda\partial_t^m\widetilde{u}_k(y,t_2)|}{\|(x,t_1)-(y,t_2)\|^\gamma} \notag\\
    = & ~ 
    \sum_{\|\lambda\|_1+m =  k_1}\sup_{\substack{{(x,t_1),(y,t_2)\in\mathbb{R}^d\times[0,1]}\\(x,t_1)\neq(y,t_2)}} \frac{|\sum_{s\in \mathcal{S}}\partial^\lambda_x\phi_s(x)\partial^m_t u_k(s,t_1)-\partial^\lambda_x \phi_s(y)\partial^m_t u_k(s,t_2)|}{\|(x,t_1)-(y,t_2)\|^\gamma} \annot{By \eqref{eq:construction_of_tilde_u}}\\
    \leq & ~
    e\cdot(2k_1)^{2k_1} M^d\sum_{n'\leq k_1}\sup_{t_1,t_2\in[0,1],t_1\neq t_2,s\in \mathcal{S}}\frac{|\partial^m_t u_k(s,t_1)-\partial^m_t u_k(s,t_2)|}{|t_1-t_2|^\gamma} \annot{By \eqref{eq:bound_of_phi_derivative}}\\
    = & ~
    e\cdot(2k_1)^{2k_1} M^d \cdot (\sum_{n'= k_1}\sup_{t_1,t_2\in[0,1],t_1\neq t_2,s\in \mathcal{S}}\frac{|\partial^m_t u_k(s,t_1)-\partial^m_t u_k(s,t_2)|}{|t_1-t_2|^\gamma} \notag\\
    & ~ \hspace{7em}
    +\sum_{n'< k_1}\sup_{t_1,t_2\in[0,1],t_1\neq t_2,s\in \mathcal{S}}\frac{|\partial^m_t u_k(s,t_1)-\partial^m_t u_k(s,t_2)|}{|t_1-t_2|^\gamma}) \notag\\
    \leq & ~
    e\cdot(2k_1)^{2k_1} M^d \cdot (\sum_{n'= k_1}\sup_{t,t_1,t_2\in[0,1],t_1\neq t_2,s\in \mathcal{S}}\frac{|\partial^m_t u_k(s,t_1)-\partial^m_t u_k(s,t_2)|}{|t_1-t_2|^\gamma} \notag\\
    & ~ \hspace{7em}
    +\sum_{n'< k_1}\sup_{t_1,t_2\in[0,1],t_1\neq t_2,s\in \mathcal{S}}\frac{\|\partial^{n'+1}u_k(s,t)\|_{L^\infty}\cdot|t_1-t_2|}{|t_1-t_2|^\gamma}) \annot{By Newton-Leibniz formula}\\
    \leq & ~
    e\cdot(2k_1)^{2k_1} M^d \cdot (K+\sum_{n'<k_1}K) \annot{$u(s,t)\in\mathcal{H}^\beta_{1,M^d}([0,1],K)$ and $|t_1-t_2|^{1-\gamma}\leq 1$}\\
    \label{eq:bound_on_gamma_part}
    = & ~
    e\cdot (k_1+1)(2k_1)^{2k_1}KM^d.
\end{align}

\textbf{Step 5: Altogether.}
Combing \eqref{eq:bound_on_derivative_part} and \eqref{eq:bound_on_gamma_part}, we get 
\begin{align*}
    \widetilde{u}(x,t)\in\mathcal{H}^\beta_{d+1,M^d}(\mathbb{R}^d\times[0,1],e\cdot(k_1+2)(2k_1)^{2k_1} KM^d).
\end{align*}
This completes the proof.

\begin{align}
    \sum_{\|\lambda\|_1+m\leq k_1} \|\partial_x^\lambda\widetilde{u}_k(x,t)\|_{L^\infty} 
    \leq & ~ 
    \sum_{\|\lambda\|_1+m\leq k_1}\sum_{s\in \mathcal{S}} \|\partial_x^\lambda\phi_s(x)\partial^{m}_t u_k(s,t)\|_{L^\infty} 
    \annot{By \eqref{eq:construction_of_tilde_u}}\\
    \leq & ~
    e\cdot(2k_1)^{2k_1} \sum_{m\leq k_1}\sum_{s\in \mathcal{S}} \|\partial^{m}_t u_k(s,t)\|_{L^\infty} 
    \annot{By \eqref{eq:bound_of_phi_derivative}}\\
    = & ~
    e\cdot(2k_1)^{2k_1} \sum_{s\in \mathcal{S}} \sum_{m\leq k_1}\|\partial^{m}_t u_k(s,t)\|_{L^\infty} \annot{Interchange the order of summations}\\
    \leq & ~
    \label{eq:bound_on_derivative_part}
    e\cdot(2k_1)^{2k_1} KM^d,
\end{align}

To start with, recall from \cref{sec:preliminaries} that when constructing a factorized path, the probability path has a factorized generating velocity of the form
\begin{align}
\label{eq:expression_of_general_velocity_factorize}
    u_t(y,x) = \sum_i \delta(y^{\widebar{i}}, x^{\widebar{i}}), u_t^i(y^i, x),
\end{align}
where $\widebar{i} = (1,\dots,i-1,i+1,\dots,d)$ denotes all indices except $i$.

\label{lem:bridge_gap_from_discrete_to_continuous_mixture_path}
Consider velocity function $u(x,t)$ with the form \eqref{eq:expression_of_universal_velocity_of_mixture_path} generating mixture path.
For each $x\in\mathcal{S}$ and coordinate $i \in [d]$, 
let $t \mapsto u^i(x,t) \in \mathcal{H}^\beta_{1,M}([t_0,T],K)$ with $\beta=k_1+\gamma\ge 1$, where  $k=\lfloor \beta \rfloor$ and $\gamma\in[0,1)$.  
Then there exists an continuous extension $\widetilde{u}^i \in \mathcal{H}^{\beta}_{d+1,M}(\mathbb{R}^{d}\times[0,1],C)$  such that
\begin{align*}
    \widetilde{u}(s,t)=u(s,t) ~~~~\text{for all}~ s\in\mathcal{S}, t\in[t_0,T],
\end{align*}
where the H\"older norm $C = e\cdot(k_1+2)(2k_1)^{2k_1} KM$.

The construction of $\widetilde{u}(x,t)$ is same as the construction in the proof of \cref{lem:bridge_gap_from_discrete_to_continuous}.
We restate it for completeness.
Let $\eta(t)$ be as defined in \cref{lem:property_of_bump_function}.
For $s\in \mathcal{S}$, we define $\phi_s(x)$ as:
\begin{align*}
    \phi_s(x)=\eta(e^2\|x-E (s)\|^2).
\end{align*}
Then we construct $\widetilde{u}(x,t)$ as:
\begin{align}
\label{eq:construction_of_tilde_u_mixture_path}
\widetilde{u}^i(x,t)=\sum_{s\in \mathcal{S}} \phi_s(x)\cdot u^i(s,t). 
\end{align}
This construction takes the same form as in \eqref{eq:construction_of_tilde_u}, while $u$ and $\widetilde{u}$ has output dimension of $M$ in mixture path case instead of $M^d$.
Then $\widetilde{u}^i(s,t)=u^i(s,t)$ for every $s\in \mathcal{S}$ given that $\phi_s(s)=1$.

The  computation of H\"older constant of $\widetilde{u}^i(x,t)$ is exactly in the same form to the computation in proof of \cref{lem:bridge_gap_from_discrete_to_continuous}, while the only difference is to replace $M^d$ with $M$.

\label{lem:lipschitz_of_tilde_u}
Suppose that for every given $s\in \mathcal{S}$, it holds $\|u(s,t)\|_2\leq M_u$ and $u(s,t)$ is Lipschitz continuous under $\ell_2$-norm with respect to $t$, with Lipschitz constant $L_u$. 
Then $\widetilde{u}(x,t)$ defined in the proof of \cref{lem:bridge_gap_from_discrete_to_continuous} is Lipschitz continuous under $\ell_2$-norm with respect to $(x,t)$, with Lipschitz constant $\max\{L_u,4e\sqrt{d}M_u\}$.

\label{lem:lipschitz_of_tilde_u_mixture_path}
Consider $u^i(x,t)$ under mixture path setting with the form \eqref{eq:expression_of_universal_velocity_of_mixture_path} .
Then $\widetilde{u}^i(x,t)$ comstructed in the proof of \cref{lem:bridge_gap_from_discrete_to_continuous_mixture_path} is Lipschitz continuous under $\ell_2$-norm with respect to $(x,t)$ when $t\in[t_0,T]$, with Lipschitz constant $L_{\widetilde{u}}\lesssim 1$.

\label{lem:bound_integral_with_local_lipschitz}
Suppose that $f:\mathbb{R}^{d\times L}\to \mathbb{R}^{d\times L}$ is Lipschitz continuous under Frobenius norm, with Lipschitz constant $L_f$.
Let $n=dL$.
If there exists $X\in\mathbb{R}^{d\times L}$ such that $\|f(X)\|_F\geq a>0$, then it holds:
\begin{align*}
    (\int\|f(Z)\|_F^2\dd Z)^{1/2}\geq (\frac{2S_n}{n(n+1)(n+2)})^{1/2}\frac{a^\frac{n+2}{2}}{L_f^\frac{n}{2}},
\end{align*}
where $S_n$ denote the surface area of the unit sphere in $n$-dimensional Euclidean space.

\label{lem:bound_local_with_integral_lipschitz}
Suppose that $f:[-I,I]^{d\times L}\to \mathbb{R}^{d\times L}$ is Lipschitz continuous on a bounded domain under Frobenius norm, with Lipschitz constant $L_f$.
Let $n=dL$.
Let $(\int\|f(Z)\|_F^2\dd Z)^{1/2}\leq b$, then for all $Z\in[-I,I]^{d\times L}$ it holds:
\begin{align*}
    \|f(Z)\|_F\lesssim b^\frac{2}{n+2}L_f^\frac{n}{n+2} .
\end{align*}

\label{thm:approximation_theorem_discrete_mixture_path_re}
Let $u^i(x,t)$ be the factorized velocity field for coordinate $i \in [d]$ under mixture path setting.
Assume \cref{ass:holder_smoothness} holds,
then for any $\epsilon \in (0,1)$, there exists a transformer network $u^i_\theta(x,t)\in\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F})$ satisfying that for any $t\in[t_0,T]$:
\begin{align*}
    \sum_{x\in \mathcal{S}}\|u^i_\theta(x,t)-u^i(x,t)\|^2_2\cdot p_t(x) \lesssim  \epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}},
