we define the loss of certain function $f$ with respect to some certain end point $x$ as:
\begin{align*}
    \ell^{i_0}(x;f):=\int_{t_0}^T \underset{X_0\sim p_0,X_t\sim p_{t|x_0=X_0,x_1=x}}{{\mathbb{E}}}\|u^{i_0}(X_t,t)-f(X_t,t)\|_2^2 \dd t.

For a factorized discrete flow matching network $u^{i_0}_\theta$ with parameter $\Theta^{i_0}$, its performance in velocity estimation is measured by the factorized discrete flow matching risk, which is defined as:
\begin{align}\label{eq:definition_of_risk_factorize}
    \mathcal{R}^{i_0}(\Theta):=\int_{t_0}^T\underset{X_t\sim p_t}{{\mathbb{E}}}\|u^{i_0}(X_t,t)-u^{i_0}_\theta(X_t,t)\|_2^2 \dd t.
\end{align}

In practice, we evaluate the performance of the factorized network $u^{i_0}_\theta$ using factorized empirical discrete flow matching risk, which is defined as:
\begin{align}\label{eq:definition_of_empirical_risk_factorize}
    \widehat{\mathcal{R}}^{i_0}(\Theta^{i_0}):=\frac{1}{n}\sum_{i=1}^n\ell^{i_0}(x_i;u^{i_0}_\theta)-\frac{1}{n}\sum_{i=1}^n\ell^{i_0}(x_i;u^{i_0}),
\end{align}
where $\{x_i\}_{i=1}^n$ are n i.i.d samples and $u^{i_0}$ is the true velocity.

\label{lem:expectation_of_empirical_risk_equal_to_risk_factorize}
For a factorized discrete flow matching network $u^{i_0}_\theta(x,t)$ with parameters noted as $\Theta^{i_0}$ and i.i.d samples $\{x_i\}_{i=1}^n$, it holds:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\Theta^{i_0})]=\mathcal{R}^{i_0}(\Theta^{i_0}).
\end{align*}

\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\Theta^{i_0})]= & ~
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\frac{1}{n}\sum_{i=1}^n\ell^{i_0}(x_i;u^{i_0}_\theta)]-\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\frac{1}{n}\sum_{i=1}^n\ell^{i_0}(x_i;u^{i_0})] \annot{By \eqref{eq:definition_of_empirical_risk_factorize}}\\
    = & ~
    \mathcal{L}^{i_0}_{\rm CDFM}(\Theta^{i_0})-\mathcal{L}^{i_0}_{\rm CDFM}(\Theta^{i_0, \rm true}) \\
    = & ~
    \mathcal{R}^{i_0}(\Theta^{i_0})-\mathcal{R}^{i_0}(\Theta^{i_0, \rm true}) \annot{By gradient equivalence of $\mathcal{L}^{i_0}_{\rm DFM}$ and $\mathcal{L}^{i_0}_{\rm CDFM}$} \\
    = & ~
    \mathcal{R}^{i_0}(\Theta^{i_0}). \annot{$\mathcal{R}^{i_0}(\Theta^{i_0, \rm true})=0$}
\end{align*}

\label{def:definition_of_covering_number}
Consider a vector-valued function class $\mathcal{F}$. 
For $\epsilon>0$, a point set $\{z_i\}_{i=1}^n$ and a norm $\|\cdot\|$ , the quantity $\mathcal{N}_\infty(\mathcal{F};\epsilon;\{z_i\}_{i=1}^n;\|\cdot\|)$ denotes the minimal cardinality of a subset (a cover) $\mathcal{C}\subset\mathcal{F}$ such that, for any $f\in\mathcal{F}$, there exists $\widehat{f}\in\mathcal{C}$ such that:
\begin{align*}
    \max_{1\leq i\leq n}\|f(z_i)-\widehat{f}(z_i)\|\leq \epsilon.
\end{align*}
We call $\mathcal{N}_\infty(\mathcal{F};\epsilon;\{z_i\}_{i=1}^n;\|\cdot\|)$ the $\epsilon$-covering number of $\mathcal{F}$ with respect to point set $\{z_i\}_{i=1}^n$.
We further set:
\begin{align*}
    \mathcal{N}_\infty(\mathcal{F};\epsilon;m;\|\cdot\|)=\max_{\{z_i\}_{i=1}^m}\mathcal{N}_\infty(\mathcal{F};\epsilon;\{z_i\}_{i=1}^m;\|\cdot\|).
\end{align*}

\label{lem:covering_number_of_general_transformer_network_mixture_path}
Let $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F},L_\mathcal{T})$ represent the class of transformer network with parameter bound.
Then for data points $x$ such that $\|x\|_2\leq B_X$, we have:
\begin{align*}
    & ~ \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon,n,\|\cdot\|_2) \\
    \leq & ~
    \frac{\log(nL_\mathcal{T})}{\epsilon^2}\alpha^2(d_0^\frac{2}{3}(C_F^{2,\infty})^\frac{2}{3}+d_0^\frac{2}{3}(2(C_F)^2C_{OV}C_{KQ}^{2,\infty})^\frac{2}{3}+2((C_F)^2C_{OV}^{2,\infty})^\frac{2}{3})^3,
\end{align*}
where $\alpha=(C_F)^2C_{OV}(1+4C_{KQ})(B_X+C_E)$.

\label{lem:covering_number_of_transformer_in_approximation_theory_mixture_path}
Let $\epsilon_c>0$. 
Consider the transformer class $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F})$ with parameter bound given in \cref{thm:approximation_theorem_discrete_mixture_path_re} and $x_i$ satisfying $x_i\in \mathcal{S}$.
Then the $\epsilon_c$-covering number of $\mathcal{T}^{h,s,r}_R$ has the following upper bound:
\begin{align*}
    \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon_c,n,\|\cdot\|_2)\lesssim
    \frac{\log(nM)}{\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}.
\end{align*}

The proof is modified from proof of Lemma J.2 of \citep{hu2024statistical}.

From \cref{thm:approximation_theorem_discrete_mixture_path_re}, we have the bounds on transformer parameters:
\begin{align}\label{eq:approximation_parameter_bound_estimation_part_mixture_path}
    & ~C_{KQ},C^{2,\infty}_{KQ}=\widetilde{O}(M^{6d_0+3}\epsilon^{-4d_0-2});C_{OV},C^{2,\infty}_{OV}=O(M^{-\frac{1}{2}}\epsilon) \notag\\
    & ~C_{F},C^{2,\infty}_{F}=O(M^2\epsilon^{-1});C_E=O(M);L_\mathcal{T}=O(M^{6d_0+\frac{25}{2}}).
\end{align}
We first use parameter in \eqref{eq:approximation_parameter_bound_estimation_part_mixture_path} to compute $\alpha$ and get:
\begin{align*}
\alpha \lesssim (M^2\epsilon^{-1})^2\cdot M^{-\frac{1}{2}}\epsilon\cdot M^{6d_0+3}\epsilon^{-4d_0-2}\cdot M=M^{6d_0+\frac{15}{2}}\epsilon^{-4d_0-3}.
\end{align*}
Further, by \cref{lem:covering_number_of_general_transformer_network_mixture_path} we have:
\begin{align*}
    & ~ \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon_c,n,\|\cdot\|_2) \\
    \lesssim & ~
    \frac{\log(nL_\mathcal{T})}{\epsilon_c^2}\alpha^2(d_0^\frac{2}{3}(2(C_F)^2C_{OV}C_{KQ}^{2,\infty})^\frac{2}{3})^3 \\
    \lesssim & ~
    \frac{\log(nM)}{\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}.
\end{align*}
This completes the proof.

\label{lem:covering_number_bounds_for_loss_function_class_mixture_path}
Let $\epsilon_c>0$ and $i_0\in[M]$.
Suppose that for every given $x\in \mathcal{S}$, $u^{i_0}(x,t)$ represent the velocity field of $x$ at time $t$ that follows mixture path setting \eqref{eq:expression_of_universal_velocity_of_mixture_path}.
We define the factorized loss function class by 
\begin{align*}
F^{i_0}_{\rm loss}:=\{\ell^{i_0}(x;u^{i_0}_\theta)|u^{i_0}_\theta\in\mathcal{T}^{h,s,r}_R\},
\end{align*}
where $\mathcal{T}^{h,s,r}_R$ is the transformer class with parameter bound given in \cref{thm:approximation_theorem_discrete_mixture_path}.

Then we have:
\begin{align*}
    \log\mathcal{N}(F^{i_0}_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)\lesssim \frac{\log(M)-\log(\epsilon_c)}{\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}.
\end{align*}

\label{lem:generalization_bound_general_mixture_path}
Let $\widehat{u}^{i_0}_\theta$ with parameter $\widehat{\Theta}^{i_0}$ be the velocity estimator trained by minimizing $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
For simplicity, we use $\mathcal{N}$ to denote $\mathcal{N}(F^{i_0}_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)$.
Then we bound (I), the generalization bound as:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0}) -\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})] 
    \lesssim 
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})] + O(\frac{\kappa}{n} 
    \log \mathcal{N} + \epsilon_c),
\end{align*}
where $\kappa$ denote the upper bound of $\ell^{i_0}(x;u^{i_0}_\theta)$.

\label{lem:empirical_risk_bound_of_trained_network_mixture_path}
Consider the transformer class $\mathcal{T}^{h,s,r}_R$ with parameter bound given in \cref{thm:approximation_theorem_discrete_mixture_path_re}.
Let $\widehat{u}^{i_0}_\theta\in\mathcal{T}^{h,s,r}_R$ with parameter $\widehat{\Theta}^{i_0}$ be the factorized velocity estimator under mixture path setting trained by minimizing $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
Let factorized empirical risk $\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})$ be as defined in \eqref{eq:definition_of_empirical_risk_factorize}.
Then we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})]\lesssim   \epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}}.
\end{align*}

\label{thm:velocity_estimation_extension_mixture_path_re}
Let $\widehat{u}^{i_0}_\theta\in\mathcal{T}^{h,s,r}_R$ with parameter $\widehat{\Theta}^{i_0}$ be the factorized velocity estimator under mixture path setting trained by minimizing $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
Then for large enough $n$ we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})] \lesssim M^{12d_0+25}n^{-\frac{ 1}{4Md_0+3M+8d_0+9}}(\log n)^{\frac{1}{4Md_0+3M+8d_0+9}}
\end{align*}

Recall the decomposition given in \eqref{eq:risk_decomposition_factorize}:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})]=\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})-\widehat{\mathcal{R}^{i_0}}(\widehat{\Theta}^{i_0})]+\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})].
\end{align*}
Substituting what we get in \cref{lem:generalization_bound_general_mixture_path} and \cref{lem:empirical_risk_bound_of_trained_network_mixture_path} into the decomposition, we get:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})]\lesssim & ~
    O(\frac{\kappa}{n}\log\mathcal{N}+\epsilon_c)+2\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}^{i_0}(\widehat{\Theta}^{i_0})] \annot{By \cref{lem:generalization_bound_general_mixture_path}} \\
    \lesssim & ~
    O(\frac{\kappa}{n}\log\mathcal{N}+\epsilon_c)+\epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}} \annot{By \cref{lem:empirical_risk_bound_of_trained_network_mixture_path}}\\
    \lesssim & ~
    \frac{\log(M)-\log(\epsilon_c)}{n\epsilon_c^2}M^{24d_0+28}\epsilon^{-16d_0-12}+\epsilon_c+\epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}}. \annot{By \cref{lem:covering_number_bounds_for_loss_function_class_mixture_path} and $\kappa\lesssim 1$ under mixture path setting}
\end{align*}
Next, we choose proper $\epsilon,\epsilon_c$ to get a optimal bound for the estimation rates.

First, we let $\epsilon_c=(\frac{\log(n\epsilon)M^{24d_0+28}\epsilon^{-16d_0-12}}{n})^{1/3}$ and get
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})]\lesssim & ~
    (\log(n\epsilon))^{1/3}M^{\frac{24d_0+28}{3}}\epsilon^{-\frac{16d_0+12}{3}}n^{-\frac{1}{3}}+\epsilon^\frac{4}{M+2}M^{\frac{12Md_0+25M}{M+2}}.
\end{align*}

Next, let $\epsilon=M^{-\frac{3}{4}}n^{-\frac{M+2}{16Md_0+12M+32d_0+36}}(\log n)^{\frac{M+2}{16Md_0+12M+32d_0+36}}$, then for large enough $n$ we get:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}^{i_0}(\widehat{\Theta}^{i_0})] \lesssim M^{12d_0+25}n^{-\frac{ 1}{4Md_0+3M+8d_0+9}}(\log n)^{\frac{1}{4Md_0+3M+8d_0+9}}.
\end{align*}
This completes the proof.

\label{thm:main_proof_distribution_estimation_extension_mixture_path_re}
For any coordinate $i_0\in[d]$, let $\widehat{u}^{i_0}_\theta$  be the $i$-th velocity estimator trained by minimizing empirical conditional discrete flow matching loss $\widehat{\mathcal{L}}^{i_0}_{\rm CDFM}$ following \eqref{eqn:cdfm_loss_empirical}.
Let $P$ denote the true distribution and $\widehat{P}$ the distribution generated by the discrete flow matching framework with factorized velocity estimators $\{\widehat{u}^{i_0}_\theta\}_{i^0=1}^d$.
Then for a vocabulary size $M$, the expected total variation distance $\text{TV}(P,\widehat{P})$ over training data $\{x_i\}_{i=1}^n$ is bounded by:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\text{TV}(P,\widehat{P})]\lesssim M^{6d_0+13}\exp(M)n^{-\frac{ 1}{8Md_0+6M+16d_0+18}}(\log n)^{\frac{1}{8Md_0+6M+16d_0+18}}.
\end{align*}

From \cref{thm:error_bound_dfm}, we have:
\begin{align*}
    {\rm TV}(P,\widehat{P})
    \lesssim 
    \sqrt{M} \exp(M_u) 
    \sum_{i_0 \in [d]} \sqrt{\mathcal{R}^{i_0}(\widehat{\Theta})}.
\end{align*}
Taking expectation on both sides and recalling that $M_u=O(1)$ under mixture setting, we obtain:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\text{TV}(P,\widehat{P})]\lesssim & ~
    \sqrt{M}\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\sum_{i_0 \in [d]} \sqrt{\mathcal{R}^{i_0}(\widehat{\Theta})}] \\
    \lesssim & ~
    M^{6d_0+13}n^{-\frac{ 1}{8Md_0+6M+16d_0+18}}(\log n)^{\frac{1}{8Md_0+6M+16d_0+18}}. \annot{By \cref{thm:velocity_estimation_extension_mixture_path_re}}
\end{align*}
This completes the proof.

\label{lem:lipschitz_of_tilde_u_general_case}
Suppose that for every given $s\in \mathcal{S}$, it holds $\|u(s,t)\|_2\leq M_u$ and $u(s,t)$ is Lipschitz continuous under $\ell_2$-norm with respect to $t$, with Lipschitz constant $L_u$. 
Then $\widetilde{u}(x,t)$ defined in the proof of \cref{lem:bridge_gap_from_discrete_to_continuous} is Lipschitz continuous under $\ell_2$-norm with respect to $(x,t)$, with Lipschitz constant $\max\{L_u,4e\sqrt{d}M_u\}$.

\label{lem:bound_local_with_integral_lipschitz_general_case}
Suppose that $f:[-I,I]^{d\times L}\to \mathbb{R}^{d\times L}$ is Lipschitz continuous on a bounded domain under Frobenius norm, with Lipschitz constant $L_f$.
Let $n=dL$.
Let $(\int\|f(Z)\|_F^2\dd Z)^{1/2}\leq b$, then for all $Z\in[-I,I]^{d\times L}$ it holds:
\begin{align*}
    \|f(Z)\|_F\lesssim b^\frac{2}{n+2}L_f^\frac{n}{n+2} .
\end{align*}

\label{thm:approximation_theorem_discrete_re}
Suppose that for every given $x\in \mathcal{S}$, $u(x,t)$ is bounded and Lipschitz continuous with respect to $t$, such that $\|u(x,t)\|_2\leq M_u$ and Lipschitz constant is $L_u$.
Then for every $\epsilon>0$, there exists a transformer network $u_\theta(x,t)\in\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F})$ satisfying that for every $t\in[0,1]$:
\begin{align*}
    \sum_{x\in \mathcal{S}}\|u_\theta(x,t)-u(x,t)\|^2_2\cdot p_t(x) \lesssim  \epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}},
\end{align*}
where $d_0$ is the transformer feature dimension.
The parameter bound of the transformer network class follows:
\begin{align*}
    & ~C_{KQ},C^{2,\infty}_{KQ}=\widetilde{O}(M^{2dd_0+d+4d_0+2}\epsilon^{-4d_0-2});\quad C_{OV},C^{2,\infty}_{OV}=O(M^{-\frac{1}{2}d}\epsilon) \notag\\
    & ~C_{F},C^{2,\infty}_{F}=O(M^{d+1}M_u\epsilon^{-1});\quad C_E=O(M^d),
\end{align*}
where $O(\cdot)$ hides polynomial factors depending on $d,d_0$, $\widetilde{O}(\cdot)$ hides polynomial factors depending on $d,d_0$ and logarithmic factors depending on $M$.

\begin{align*}
    u_\theta^{\rm reshape}(Z)= F^{\rm FF}_1\circ F^{\rm SA}\circ F^{\rm FF}_2\circ F^{\rm E}\in\mathcal{T}^{h,s,r}(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F}),
\end{align*}

\begin{align*}
    L_\theta^{\rm reshape}\leq & ~
    (1+2M^{2d}C_{OV}C_{KQ}+h\frac{M^d}{d_0}C_{OV})\cdot(C_F^2+1)^2\\
    \lesssim & ~
    (C_F)^2\cdot M^{2d}\cdot h C_{KQ}C_{OV}\cdot(C_F)^2 \\
    \lesssim & ~
    M^{2dd_0+\frac{13}{2}d+4d_0+6}M_u^4. \annot{By \eqref{eq:bound_of_parameter_main_proof_stat_rate} and dropping terms of $\epsilon$}
\end{align*}

\begin{align*}
    \|u_\theta(x,t)-\widetilde{u}(x,t)\|^2_2\leq & ~
    \|u_\theta^{\rm reshape}\circ R_1(x,t)-u^{\rm reshape}\circ R_1(x,t)\|^2_F \\
    = & ~
    \|h(R_1(x,t))\|^2_F 
    \annot{By definition of $h$}\\
    \lesssim & ~
    \epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}}, \annot{By \cref{lem:bound_local_with_integral_lipschitz_general_case}}
\end{align*}

\label{lem:expectation_of_empirical_risk_equal_to_risk}
For a discrete flow matching network $u_\theta(x,t)$ with parameters noted as $\Theta$ and i.i.d samples $\{x_i\}_{i=1}^n$, it holds:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}(\Theta)]=\mathcal{R}(\Theta).
    \end{align*}

\label{lem:covering_number_of_general_transformer_network}
Let $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F},L_\mathcal{T})$ represent the class of transformer network with parameter bound.
Then for data points $x$ such that $\|x\|_2\leq B_X$, we have:
\begin{align*}
    & ~ \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon,n,\|\cdot\|_2) \\
    \leq & ~
    \frac{\log(nL_\mathcal{T})}{\epsilon^2}\alpha^2(d_0^\frac{2}{3}(C_F^{2,\infty})^\frac{2}{3}+d_0^\frac{2}{3}(2(C_F)^2C_{OV}C_{KQ}^{2,\infty})^\frac{2}{3}+2((C_F)^2C_{OV}^{2,\infty})^\frac{2}{3})^3,
\end{align*}
where $\alpha=(C_F)^2C_{OV}(1+4C_{KQ})(B_X+C_E)$.

\label{lem:covering_number_of_transformer_in_approximation_theory}
Let $\epsilon_c>0$. 
Consider the transformer class $\mathcal{T}^{h,s,r}_R(C_\mathcal{T},C^{2,\infty}_{KQ},C_{KQ},C^{2,\infty}_{OV},C_{OV},C_{E},C^{2,\infty}_{F},C_{F})$ with parameter bound given in \cref{thm:approximation_theorem_discrete_re} and $x_i$ satisfying $x_i\in \mathcal{S}$.
Then the $\epsilon_c$-covering number of $\mathcal{T}^{h,s,r}_R$ satisfies:
\begin{align*}
    \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon_c,n,\|\cdot\|_2)\lesssim
    \frac{\log(nMM_u\epsilon)}{\epsilon_c^2}M^{8dd_0+12d+16d_0+16}M_u^8\epsilon^{-16d_0-12}.
\end{align*}

The proof is modified from the proof of \cref{lem:covering_number_of_transformer_in_approximation_theory_mixture_path}.

From \cref{thm:approximation_theorem_discrete_re}, we have:
\begin{align}\label{eq:approximation_parameter_bound_estimation_part}
    & ~C_{KQ},C^{2,\infty}_{KQ}=\widetilde{O}(M^{2dd_0+d+4d_0+2}\epsilon^{-4d_0-2});C_{OV},C^{2,\infty}_{OV}=O(M^{-\frac{1}{2}d}\epsilon) \notag\\
    & ~C_{F},C^{2,\infty}_{F}=O(M^{d+1}M_u\epsilon^{-1});C_E=O(M^d);L_\mathcal{T}=O(M^{2dd_0+\frac{13}{2}d+4d_0+6}M_u^4).
\end{align}
Then we substitute \eqref{eq:approximation_parameter_bound_estimation_part} into \cref{lem:covering_number_of_general_transformer_network} and get:
\begin{align*}
\alpha \lesssim M^{2d+2}M_u^2\epsilon^{-2}\cdot M^{-\frac{1}{2}d}\epsilon\cdot M^{2dd_0+d+4d_0+2}\epsilon^{-4d_0-2}\cdot M^d=M^{2dd_0+\frac{7}{2}d+4d_0+4}M_u^2\epsilon^{-4d_0-3}.
\end{align*}
Through further computation, we have
\begin{align*}
    & ~ \log\mathcal{N}(\mathcal{T}^{h,s,r}_R,\epsilon_c,n,\|\cdot\|_2) \\
    \lesssim & ~
    \frac{\log(nL_\mathcal{T})}{\epsilon_c^2}\alpha^2(d_0^\frac{2}{3}(2(C_F)^2C_{OV}C_{KQ}^{2,\infty})^\frac{2}{3})^3 \\
    \lesssim & ~
    \frac{\log(nMM_u)}{\epsilon_c^2}M^{8dd_0+12d+16d_0+16}M_u^8\epsilon^{-16d_0-12}.
\end{align*}
This completes the proof.

\label{lem:covering_number_bounds_for_loss_function_class}
Let $\epsilon_c>0$.
Suppose that for every given $x\in \mathcal{S}$, $u(x,t)$ is bounded and Lipschitz continuous with respect to $t$, such that $\|u(x,t)\|_2\leq M_u$ and Lipschitz constant is $L_u$.
We define the loss function class by 
\begin{align*}
F_{\rm loss}:=\{\ell(x;u_\theta)|u_\theta\in\mathcal{T}^{h,s,r}_R\},
\end{align*}
where $\mathcal{T}^{h,s,r}_R$ is the transformer class with parameter bound given in \cref{thm:approximation_theorem_discrete_re}.
Then we have:
\begin{align*}
    \log\mathcal{N}(F_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)\lesssim \frac{\log(MM_u)-\log(\epsilon_c)}{\epsilon_c^2}M^{8dd_0+12d+16d_0+16}M_u^{10}\epsilon^{-16d_0-12}.
\end{align*}

\label{lem:generalization_bound_general}
Let $\widehat{u}_\theta$ with parameter $\widehat{\Theta}$ be the velocity estimator trained by minimizing $\widehat{\mathcal{L}}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
For simplicity, we use $\mathcal{N}$ to denote $\mathcal{N}(F_{\rm loss},\epsilon_c,\{x_i\}_{x_i\in \mathcal{S}},|\cdot|)$.
Then we bound (I), the generalization bound as:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})-\widehat{\mathcal{R}}(\widehat{\Theta})] \lesssim \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}(\widehat{\Theta})]+O(\frac{\kappa}{n}\log\mathcal{N}+\epsilon_c),
\end{align*}
where $\kappa$ denote the upper bound of $\ell(x;u_\theta)$.

\label{lem:empirical_risk_bound_of_trained_network}
Consider the transformer class $\mathcal{T}^{h,s,r}_R$ with parameter bound given in \cref{thm:approximation_theorem_discrete_re}.
Let $\widehat{u}_\theta\in\mathcal{T}^{h,s,r}_R$ with parameter $\widehat{\Theta}$ be the velocity estimator trained by minimizing $\widehat{\mathcal{L}}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
Let empirical risk $\widehat{\mathcal{R}}(\widehat{\Theta})$ be as defined in \eqref{eq:definition_of_empirical_risk}.
Then we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}(\widehat{\Theta})]\lesssim   \epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}}.
\end{align*}

\label{thm:main_proof_velocity_estimation_general}
Let $\widehat{u}_\theta$ with parameter $\widehat{\Theta}$ be the velocity estimator trained by minimizing empirical conditional discrete flow matching loss $\widehat{\mathcal{L}}_{\rm CDFM}$ with i.i.d training samples $\{x_i\}_{i=1}^n$, where $x_i\in \mathcal{S}$.
Suppose that for every given $x_i\in \mathcal{S}$, $u(x_i,t)$ is bounded , such that $\|u(x_i,t)\|_2\leq M_u$.
Moreover, for every given $x_i\in \mathcal{S}$ $u(x_i,t)$ is Lipschitz continuous with respect to $t$.
Then for large enough $n$ we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})]\lesssim  M_u^8M^{4dd_0+12d+8d_0+12}n^{-\frac{ 1}{4M^dd_0+3M^d+8d_0+9}}(\log n)^{\frac{1}{4M^dd_0+3M^d+8d_0+9}}.
\end{align*}

Recall the decomposition given in \eqref{eq:risk_decomposition}:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})]=\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})-\widehat{\mathcal{R}}(\widehat{\Theta})]+ \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}(\widehat{\Theta})].
\end{align*}
Substituting the result of \cref{lem:generalization_bound_general} and \cref{lem:empirical_risk_bound_of_trained_network} into the decomposition, we get:
\begin{align*} 
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})]\lesssim & ~
    O(\frac{\kappa}{n}\log\mathcal{N}+\epsilon_c)+2\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\widehat{\mathcal{R}}(\widehat{\Theta})] \annot{By \cref{lem:generalization_bound_general}} \\
    \lesssim & ~
    O(\frac{\kappa}{n}\log\mathcal{N}+\epsilon_c)+\epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}} \annot{By \cref{lem:empirical_risk_bound_of_trained_network}}\\
    \lesssim & ~
    \frac{\log(MM_u\epsilon)-\log(\epsilon_c)}{n\epsilon_c^2}M^{8dd_0+12d+16d_0+16}M_u^{12}\epsilon^{-16d_0-12} \\
    & ~ +
    \epsilon_c+\epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}}. \annot{By \cref{lem:covering_number_bounds_for_loss_function_class} and $\kappa\lesssim M_u^2$}
\end{align*}

We then choose $\epsilon$ and $\epsilon_c$ to get an optimal estimation.

First, let $\epsilon_c=(\frac{\log(n\epsilon)M^{8dd_0+12d+16d_0+16}M_u^{12}\epsilon^{-16d_0-12}}{n})^{1/3}$ and we obtain:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})]\lesssim & ~
    (\log(n\epsilon))^{1/3}M_u^4M^{\frac{8dd_0+12d+16d_0+16}{3}}\epsilon^{-\frac{16d_0+12}{3}}n^{-\frac{1}{3}}\\
    & ~ +\epsilon^\frac{4}{M^d+2}M^{\frac{4M^ddd_0+13M^dd+8M^dd_0+12M^d}{M^d+2}}M_u^{\frac{8M^d}{M^d+2}}.
\end{align*}

Next, let $\epsilon=M^{-\frac{1}{4}d+1}n^{-\frac{M^d+2}{16M^dd_0+12M^d+32d_0+36}}(\log n)^{\frac{M^d+2}{16M^dd_0+12M^d+32d_0+36}}$, then for large enough $n$ we get:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\mathcal{R}(\widehat{\Theta})] \lesssim M_u^8M^{4dd_0+12d+8d_0+12}n^{-\frac{ 1}{4M^dd_0+3M^d+8d_0+9}}(\log n)^{\frac{1}{4M^dd_0+3M^d+8d_0+9}}.
\end{align*}
This completes the proof.

\label{thm:main_proof_distribution_estimation_general}
Let $\widehat{u}_\theta$ with parameter $\widehat{\Theta}$ be the velocity estimator trained by minimizing empirical conditional discrete flow matching loss $\widehat{\mathcal{L}}_{\rm CDFM}$ in \cref{thm:main_proof_velocity_estimation_general}.
Let $P$ stand for the true distribution and $\widehat{P}$ stand for the generated distribution with discrete flow matching network $\widehat{u}_\theta$.
Then we have:
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\text{TV}(P,\widehat{P})]\lesssim M_u^4\exp(M_uM^d)M^{2dd_0+\frac{13}{2}d+4d_0+6}n^{-\frac{ 1}{8M^dd_0+6M^d+16d_0+18}}(\log n)^{\frac{1}{8M^dd_0+6M^d+16d_0+18}}.
\end{align*}

Following \cref{thm:dfm_error_bound_general}, we have:
\begin{align*}
    \text{TV}(P,\widehat{P})
    \lesssim 
    \exp(M_u)M^{\frac{d}{2}}\sqrt{\mathcal{R}(\Theta)}.
\end{align*}
We then take expectations at both sides and apply the velocity estimation rate (\cref{thm:main_proof_velocity_estimation_general}), 
\begin{align*}
    \underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\text{TV}(P,\widehat{P})]\lesssim & ~
    \exp(M_u)M^{\frac{d}{2}}\underset{\{x_i\}_{i=1}^n}{{\mathbb{E}}}[\sqrt{\mathcal{R}(\Theta)}] \\
    \lesssim & ~
    M_u^4\exp(M_u)M^{2dd_0+\frac{13}{2}d+4d_0+6}n^{-\frac{ 1}{8M^dd_0+6M^d+16d_0+18}}(\log n)^{\frac{1}{8M^dd_0+6M^d+16d_0+18}}. \annot{By \cref{thm:main_proof_velocity_estimation_general}}
\end{align*}
This completes the proof.
